#include <iostream>
#include <numbers>

// Contract: area() returns a non-negative value; draw() writes a description.
class Shape {
public:
    virtual ~Shape() = default;
    virtual double area() const = 0;
    virtual void draw(std::ostream& os) const = 0;
};

class Circle : public Shape {
public:
    explicit Circle(double r) : r_(r < 0 ? 0 : r) {}     // keeps area() >= 0.
    double area() const override { return std::numbers::pi * r_ * r_; }
    void draw(std::ostream& os) const override { os << "circle r=" << r_ << '\n'; }
private:
    double r_;
};

void report(const Shape& s) {             // no special cases for any shape.
    s.draw(std::cout);
    std::cout << "area " << s.area() << '\n';
}
// report(Circle{2.0});   works exactly like any other Shape.
```

